import{_ as s,C as n,o as i,c as r,aj as e,G as o}from"./chunks/framework.BwH0p-pt.js";const m=JSON.parse('{"title":"Association Types","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/associations/association-types.md","filePath":"3.0/associations/association-types.md","lastUpdated":1785836850000}'),d={name:"3.0/associations/association-types.md"};function l(g,t,h,p,c,y){const a=n("ImagePopup");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="association-types" tabindex="-1">Association Types <a class="header-anchor" href="#association-types" aria-label="Permalink to &quot;Association Types&quot;">​</a></h1><p>An <strong>association type</strong> is a named kind of product-to-product link — <em>Related Products</em>, <em>Cross Sells</em>, or anything you define yourself. Manage them under <strong>Catalog → Association Types</strong>.</p><h2 id="the-listing" tabindex="-1">The listing <a class="header-anchor" href="#the-listing" aria-label="Permalink to &quot;The listing&quot;">​</a></h2><p>The grid shows every type with its <strong>Code</strong>, <strong>Name</strong>, <strong>Status</strong> (Enabled / Disabled) and <strong>Position</strong>, sorted by position. You can search, filter and sort on every column. Each row offers <strong>Edit</strong> and <strong>Delete</strong>, and you can select several rows to delete them or change their status in one go.</p>',4)),o(a,{src:"/assets/3.0/images/associations/association-types-grid.png",alt:"Association types grid with code, name, status and position"}),t[1]||(t[1]=e('<h2 id="create-an-association-type" tabindex="-1">Create an association type <a class="header-anchor" href="#create-an-association-type" aria-label="Permalink to &quot;Create an association type&quot;">​</a></h2><ol><li>Go to <strong>Catalog → Association Types</strong> and click <strong>Create Association Type</strong>.</li><li>Type a <strong>Name</strong>. You are typing it in your current catalog language — the small badge next to the label shows which one.</li><li>The <strong>Code</strong> fills itself in from the name. Edit it now if you want something different; once saved it can never change.</li><li>Click <strong>Save Association Type</strong>. You land on the edit page to finish the setup.</li></ol><p>A new type starts <strong>Enabled</strong> and is placed at the end of the ordering.</p>',3)),o(a,{src:"/assets/3.0/images/associations/association-type-create-modal.png",alt:"Create Association Type modal with name and auto-generated code"}),t[2]||(t[2]=e('<h2 id="edit-an-association-type" tabindex="-1">Edit an association type <a class="header-anchor" href="#edit-an-association-type" aria-label="Permalink to &quot;Edit an association type&quot;">​</a></h2><p>The edit page has two sides: the <strong>Fields</strong> panel on the left, and the general settings on the right.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Code</strong></td><td>Read-only. Identifies the type in imports, exports and the API.</td></tr><tr><td><strong>Status</strong></td><td>Switch the type off to hide it from the product edit page without deleting anything. Links already made are kept.</td></tr><tr><td><strong>Position</strong></td><td>Controls the order in which types are listed everywhere they appear.</td></tr><tr><td><strong>Label</strong></td><td>The display name, one per catalog language — use the locale switcher to fill each language. Where a translation is missing, the code is shown instead.</td></tr></tbody></table><p>Click <strong>Update Association Type</strong> at the top to save.</p><h2 id="custom-fields-on-each-link" tabindex="-1">Custom fields on each link <a class="header-anchor" href="#custom-fields-on-each-link" aria-label="Permalink to &quot;Custom fields on each link&quot;">​</a></h2><p>A type can carry extra fields that appear on <strong>every product link</strong> of that type — for example a <em>Quantity</em> note on <em>Bundle Contents</em>, or a <em>Featured</em> flag on <em>Cross Sells</em>.</p><p>To add one, open the type and click <strong>Add Field</strong>:</p><ol><li>Type the field <strong>Name</strong> in your catalog language. The <strong>Code</strong> is generated and stays editable until you save.</li><li>Choose the <strong>Type</strong>: <strong>Text</strong> or <strong>Yes/No</strong>.</li><li>Click <strong>Save Field</strong>, then click the field again to fine-tune it.</li></ol><table tabindex="0"><thead><tr><th>Field setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>One per catalog language, editable when you reopen the field.</td></tr><tr><td><strong>Input validation</strong></td><td>Text fields only — restrict entries to a number, an email, a URL, or your own pattern.</td></tr><tr><td><strong>Value per locale</strong></td><td>When on, each catalog language gets its own value on every link.</td></tr><tr><td><strong>Required</strong></td><td>The value must be filled when the link is saved.</td></tr></tbody></table><p>Drag fields by the handle to reorder them; the product edit page follows that order. Save the page with <strong>Update Association Type</strong> when you are done.</p>',10)),o(a,{src:"/assets/3.0/images/associations/association-type-fields.png",alt:"Custom fields panel on the association type edit page"}),t[3]||(t[3]=e('<h2 id="delete-a-type" tabindex="-1">Delete a type <a class="header-anchor" href="#delete-a-type" aria-label="Permalink to &quot;Delete a type&quot;">​</a></h2><p>Use the bin icon in the grid. Deleting a type removes its product links as well, so check the type is genuinely unused first — disabling it is the reversible alternative.</p><p>The three built-in types — <strong>Related Products</strong>, <strong>Up Sells</strong> and <strong>Cross Sells</strong> — are system types. They can be edited, reordered and even disabled, but they cannot be deleted.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Access is controlled by roles. Under <strong>Settings → Users → Roles</strong>, the <em>Association Types</em> permission group lets you grant viewing, creating, editing and deleting separately, so you can let a team use association types without letting them change the setup.</p>',5))])}const f=s(d,[["render",l]]);export{m as __pageData,f as default};
